    this.exhaustion -= env.ifnGamma * 0.02 * dt;
    this.exhaustion = clamp(this.exhaustion, 0, 1);
    const anergic = this.exhaustion > 0.8;
    this.activationLevel = clamp(this.activationLevel + env.ifnGamma * dt * 0.1 - 0.02 * dt, 0, 1);
